fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let floor: i32 = h - 30;
    let mut y: i32 = host::display::state_get(0);
    let mut v: i32 = host::display::state_get(1);
    if host::display::state_get(2) == 0 {
        host::display::state_set(2, 1);
        y = 40 * 8;
        v = 0;
    }
    let down: i32 = host::display::pointer_down();
    if down == 1 && host::display::state_get(3) == 0 {
        y = 40 * 8;
        v = 0;
    }
    host::display::state_set(3, down);
    v = v + 3;
    y = y + v;
    let mut hit: i32 = 0;
    if y / 8 >= floor {
        y = floor * 8;
        hit = v;
        v = 0 - v * 4 / 5;
        if hit <= 8 { v = 0; }
    }
    if hit > 8 {
        host::audio::tone(150 + hit * 6, 90, 3);
    }
    host::display::state_set(0, y);
    host::display::state_set(1, v);
    host::display::clear(0x0c0c14);
    host::display::fill_rect(0, floor + 16, w, h - floor - 16, 0x303030);
    let mut c: i32 = 0xffaa00;
    if hit > 8 { c = 0xffffff; }
    host::display::fill_rect(w / 2 - 8, y / 8 - 16, 16, 16, c);
    host::display::draw_string(8, 8, "TAP TO DROP", 0x808080, 1);
    host::display::present();
}
